package com.sistemahospitalar.hospital.service; import com.sistemahospitalar.hospital.model.*; import com.sistemahospitalar.hospital.repository.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class ProfissionalSaudeService { private final ProfissionalSaudeRepository repo; public ProfissionalSaudeService(ProfissionalSaudeRepository repo){this.repo=repo;} public List<ProfissionalSaude> listar(){return repo.findAll();} public ProfissionalSaude salvar(ProfissionalSaude p){return repo.save(p);} public List<MedicoEspecialista> porEspecialidade(String e){return repo.findByEspecialidadeIgnoreCase(e);} }
